Structs and Memory Layout
typedef struct {
    uint8_t  a;  // 1 byte
    uint32_t b;  // 4 bytes
    uint8_t  c;  // 1 byte
} bad_struct_t;  // Size = 12 bytes (padding!)

typedef struct {
    uint32_t b;  // 4 bytes
    uint8_t  a;  // 1 byte
    uint8_t  c;  // 1 byte
} good_struct_t; // Size = 8 bytes (better packing)
