Calibration code
// Calibration constants (determined experimentally)
#define CAL_ADC_LOW     310     // ADC reading at 0°C
#define CAL_ADC_HIGH    1550    // ADC reading at 100°C
#define CAL_TEMP_LOW    0.0f    // Known temperature 1
#define CAL_TEMP_HIGH   100.0f  // Known temperature 2

float calibrate_temperature(uint16_t adc_raw) {
    // Linear interpolation
    float slope = (CAL_TEMP_HIGH - CAL_TEMP_LOW) /
                  (CAL_ADC_HIGH - CAL_ADC_LOW);
    float offset = CAL_TEMP_LOW - slope * CAL_ADC_LOW;

    return slope * adc_raw + offset;
}
Store calibration constants in flash for production

Why filter?
Raw ADC readings are noisy:
// Example noisy ADC readings
uint16_t readings[] = {2048, 2051, 2045, 2089, 2044, 2052, 2047, 2050};
//                                    ^^^^ noise spike!
Filtering smooths the signal — converts noisy samples to stable output
Trade-off: Smoother = slower response

Moving average filter
Average of last N samples:
\[y[n] = \frac{1}{N} \sum_{i=0}^{N-1} x[n-i]\]
#define FILTER_SIZE 8

uint16_t filter_buffer[FILTER_SIZE];
uint8_t filter_index = 0;

uint16_t moving_average(uint16_t new_sample) {
    static uint32_t sum = 0;

    // Subtract oldest, add newest
    sum -= filter_buffer[filter_index];
    filter_buffer[filter_index] = new_sample;
    sum += new_sample;

    // Advance circular index
    filter_index = (filter_index + 1) % FILTER_SIZE;

    return sum / FILTER_SIZE;
}

Exponential moving average (EMA)
Weighted average favoring recent samples:
\[y[n] = \alpha \times x[n] + (1-\alpha) \times y[n-1]\]
#define ALPHA 0.1f  // Smoothing factor (0 to 1)

float ema_filter(float new_sample) {
    static float filtered = 0;
    static uint8_t initialized = 0;

    if (!initialized) {
        filtered = new_sample;
        initialized = 1;
    } else {
        filtered = ALPHA * new_sample + (1 - ALPHA) * filtered;
    }

    return filtered;
}
Lower α = smoother but slower

