    for(;;) {
        HAL_GPIO_TogglePin(LED_GPIO_Port, LED_Pin);
        osDelay(1000);
    }
}

void FastLED(void *arg) {    // Normal priority
    for(;;) {
        HAL_GPIO_TogglePin(LED2_GPIO_Port, LED2_Pin);
        osDelay(fast_mode ? 50 : 200);
    }
}
// Both blink independently — that's the RTOS magic

Complete example: setup
Everything from Weeks 6–7 in one project — tasks, queues, mutex, priorities.
osMessageQueueId_t sensorQueue;   // ADC readings: producer → consumer
osMutexId_t uartMutex;            // protects printf (UART)

// main.c — HAL init, then hand off to RTOS
int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_ADC1_Init();
    MX_USART2_UART_Init();
    MX_FREERTOS_Init();  // create queues, mutex, tasks (see below)
    osKernelStart();     // scheduler takes over — never returns
}
// freertos.c — CubeMX generates this function
void MX_FREERTOS_Init(void) {
    sensorQueue = osMessageQueueNew(10, sizeof(uint16_t), NULL);
    uartMutex   = osMutexNew(NULL);
    osThreadNew(SensorTask,  NULL, &(osThreadAttr_t){
        .name = "Sensor",  .priority = osPriorityNormal, .stack_size = 128*4});
    osThreadNew(DisplayTask, NULL, &(osThreadAttr_t){
        .name = "Display", .priority = osPriorityBelowNormal, .stack_size = 256*4});
    osThreadNew(HeartbeatTask, NULL, &(osThreadAttr_t){
        .name = "Heartbeat", .priority = osPriorityLow, .stack_size = 128*4});
}

Complete example: tasks
// Producer — reads ADC at 10 Hz, sends to queue
void SensorTask(void *arg) {
    uint16_t reading;
    for(;;) {
        HAL_ADC_Start(&hadc1);
        HAL_ADC_PollForConversion(&hadc1, 10);
        reading = HAL_ADC_GetValue(&hadc1);
        HAL_ADC_Stop(&hadc1);
        osMessageQueuePut(sensorQueue, &reading, 0, 10); // 10ms timeout
        osDelay(100);
    }
}
// Consumer — waits for data, prints with mutex protection
void DisplayTask(void *arg) {
    uint16_t value;
    for(;;) {
        osMessageQueueGet(sensorQueue, &value, NULL, osWaitForever);
        float voltage = (value / 4095.0f) * 3.3f;
        osMutexAcquire(uartMutex, osWaitForever);
        printf("ADC: %u  Voltage: %.2fV\r\n", value, voltage);
        osMutexRelease(uartMutex);
    }
}
// Heartbeat (W06) — blinks LED at osPriorityLow, no queue or mutex needed
void HeartbeatTask(void *arg) { for(;;) { HAL_GPIO_TogglePin(LED_GPIO_Port, LED_Pin); osDelay(1000); } }

Race conditions are not RTOS-only
Same problem in bare-metal code — interrupts replace task switches:
volatile struct SensorPacket packet;

void main(void) {
    for (;;) {
        // IRQ can fire between any of these reads → torn read
        uint32_t ts  = packet.timestamp;
        uint16_t val = packet.value;
        uint8_t  st  = packet.status;
        display(ts, val, st);
    }
}

void SensorIRQ_Handler(void) {
    packet.timestamp = TIM2-&gt;CNT;
    packet.value     = ADC1-&gt;DR;
    packet.status    = validate(packet.value);
}
Bare-metal fixes:







Technique
How




Disable interrupts
__disable_irq() / __enable_irq() around reads


Double-read
Read twice, use only if both match


Sequence counter
Writer increments before & after; reader retries if changed









Tip


RTOS adds queues and mutexes, but the underlying problem — non-atomic multi-field access — exists whenever any preemption source (interrupt or scheduler) is present.

