            I2C_MEMADD_SIZE_8BIT, buf, 14, 100) == HAL_OK) {
        ax_r = (buf[0]  &lt;&lt; 8) | buf[1];
        ay_r = (buf[2]  &lt;&lt; 8) | buf[3];
        az_r = (buf[4]  &lt;&lt; 8) | buf[5];
        t_r  = (buf[6]  &lt;&lt; 8) | buf[7];
        gx_r = (buf[8]  &lt;&lt; 8) | buf[9];
        gy_r = (buf[10] &lt;&lt; 8) | buf[11];
        gz_r = (buf[12] &lt;&lt; 8) | buf[13];

        float temp_c = (who == 0x70)
            ? (t_r / TEMP_DIV_6500) + TEMP_OFS_6500
            : (t_r / TEMP_DIV_6050) + TEMP_OFS_6050;

        printf("A:%+5.2f %+5.2f %+5.2f g | "
               "G:%+6.1f %+6.1f %+6.1f dps | %.1fC\r\n",
               ax_r/ACCEL_LSB, ay_r/ACCEL_LSB, az_r/ACCEL_LSB,
               gx_r/GYRO_LSB,  gy_r/GYRO_LSB,  gz_r/GYRO_LSB,
               temp_c);
    }
    HAL_Delay(100);  // 10 Hz
}






Important


Different formulas! MPU6050: T_raw/340 + 36.53 · MPU6500: T_raw/333.87 + 21.00. Using the wrong one shifts the reading by ~15 °C. Expect 27–33 °C at rest (5–10 °C above ambient from die self-heating).

