Step 4.1: Parse + Scale in the Main Loop
/* USER CODE BEGIN PD */
#define ACCEL_LSB     16384.0f      /* ±2 g  */
#define GYRO_LSB        131.0f      /* ±250 °/s */
#define DT_S            0.001f      /* 1 kHz sample period */
#define ALPHA           0.98f       /* fc ≈ 3.2 Hz */
#define UART_DECIM      20          /* 50 Hz line rate */
/* USER CODE END PD */
/* USER CODE BEGIN WHILE */
while (1) {
    if (imu_ready) {
        imu_ready = 0;

        int16_t ax_r = (int16_t)((imu_raw[0]  &lt;&lt; 8) | imu_raw[1]);
        int16_t ay_r = (int16_t)((imu_raw[2]  &lt;&lt; 8) | imu_raw[3]);
        int16_t az_r = (int16_t)((imu_raw[4]  &lt;&lt; 8) | imu_raw[5]);
        int16_t gx_r = (int16_t)((imu_raw[8]  &lt;&lt; 8) | imu_raw[9]);
        int16_t gy_r = (int16_t)((imu_raw[10] &lt;&lt; 8) | imu_raw[11]);
        int16_t gz_r = (int16_t)((imu_raw[12] &lt;&lt; 8) | imu_raw[13]);

        float ax = ax_r / ACCEL_LSB;
        float ay = ay_r / ACCEL_LSB;
        float az = az_r / ACCEL_LSB;
        float gx = (gx_r - gyro_bias_x) / GYRO_LSB;
        float gy = (gy_r - gyro_bias_y) / GYRO_LSB;
        float gz = (gz_r - gyro_bias_z) / GYRO_LSB;

Step 4.2: Complementary Filter
        float roll_acc  = atan2f(ay, az)                   * 57.29578f;
        float pitch_acc = atan2f(-ax, sqrtf(ay*ay+az*az))  * 57.29578f;

        roll_deg  = ALPHA*(roll_deg  + gx*DT_S) + (1-ALPHA)*roll_acc;
        pitch_deg = ALPHA*(pitch_deg + gy*DT_S) + (1-ALPHA)*pitch_acc;
        yaw_deg  += gz * DT_S;            /* gyro-only — drifts! */
        if (yaw_deg &gt;  180) yaw_deg -= 360;
        if (yaw_deg &lt; -180) yaw_deg += 360;






Tip


Why α = 0.98? It’s a high-pass on the gyro, low-pass on the accel. At 1 kHz it gives fc = (1-α)/(2π α Δt) ≈ 3.2 Hz — taps and vibration are rejected, slow drift is corrected.

Step 4.3: Decimated UART Output
        if ((sample_idx % UART_DECIM) == 0) {
            char line[48];
            int n = snprintf(line, sizeof(line), "%.2f,%.2f,%.2f\r\n",
                             roll_deg, pitch_deg, yaw_deg);
            HAL_UART_Transmit(&huart2, (uint8_t*)line, n, 10);
        }
    }
    __WFI();         /* sleep until next IRQ */
}
/* USER CODE END WHILE */






