HD44780: minimal HAL driver
static void set_data_pins(uint8_t nib) {
    HAL_GPIO_WritePin(LCD_D4_GPIO, LCD_D4_PIN, (nib &gt;&gt; 0) & 1);
    HAL_GPIO_WritePin(LCD_D5_GPIO, LCD_D5_PIN, (nib &gt;&gt; 1) & 1);
    HAL_GPIO_WritePin(LCD_D6_GPIO, LCD_D6_PIN, (nib &gt;&gt; 2) & 1);
    HAL_GPIO_WritePin(LCD_D7_GPIO, LCD_D7_PIN, (nib &gt;&gt; 3) & 1);
}

static void lcd_write4(uint8_t nib, bool is_data) {
    HAL_GPIO_WritePin(LCD_RS_GPIO, LCD_RS_PIN, is_data);
    set_data_pins(nib);
    HAL_GPIO_WritePin(LCD_E_GPIO, LCD_E_PIN, GPIO_PIN_SET);
    HAL_Delay(1);  // E pulse width (tPW_E &gt; 450 ns)
    HAL_GPIO_WritePin(LCD_E_GPIO, LCD_E_PIN, GPIO_PIN_RESET);
}

void lcd_send(uint8_t byte, bool is_data) {
    lcd_write4(byte &gt;&gt; 4, is_data);    // upper nibble
    lcd_write4(byte & 0x0F, is_data);  // lower nibble
    HAL_Delay(1);
}

void lcd_putc(char c)          { lcd_send(c, true); }
void lcd_puts(const char *str) { while (*str) lcd_putc(*str++); }

void lcd_goto(uint8_t x, uint8_t y) {
    uint8_t cmd = 0x80 + (y == 1 ? 0x40 : 0) + x;
    lcd_send(cmd, false);
}

Walk through the call chain: lcd_puts → lcd_putc → lcd_send → lcd_write4 (×2) → set_data_pins + E pulse. Point out that lcd_goto uses the DDRAM address command (0x80 base) plus the line 1 offset (0x40) — this is a common magic number that trips people up. Ask students to calculate what address you’d send to go to column 5 of line 1: 0x80 + 0x40 + 5 = 0xC5.

HD44780: retargeting printf to LCD
// In syscalls.c — redirects printf output to the LCD
int _write(int file, char *ptr, int len) {
    (void)file;
    for (int i = 0; i &lt; len; i++) {
        if (ptr[i] != '\n')
            lcd_putc(ptr[i]);
        // Optional: handle \n as cursor-to-next-line
    }
    return len;
}
