snprintf(buf, sizeof(buf), "Temp: %d C", temp);
lcd_puts(buf);
Benefit: standard formatting functions work directly with the display — no custom string builder needed.

Warn students that retargeting printf affects all printf calls. For a larger project, prefer a dedicated lcd_printf wrapper instead. Also point out that HAL_Delay inside the driver makes this blocking.

PCD8544: SPI transaction example
void pcd8544_cmd(uint8_t cmd) {
    HAL_GPIO_WritePin(PCD8544_DC_GPIO,  PCD8544_DC_PIN,  GPIO_PIN_RESET); // DC low = command
    HAL_GPIO_WritePin(PCD8544_CE_GPIO,  PCD8544_CE_PIN,  GPIO_PIN_RESET); // select
    HAL_SPI_Transmit(&hspi1, &cmd, 1, HAL_MAX_DELAY);
    HAL_GPIO_WritePin(PCD8544_CE_GPIO,  PCD8544_CE_PIN,  GPIO_PIN_SET);   // deselect
}

void pcd8544_data(uint8_t data) {
    HAL_GPIO_WritePin(PCD8544_DC_GPIO,  PCD8544_DC_PIN,  GPIO_PIN_SET);   // DC high = data
    HAL_GPIO_WritePin(PCD8544_CE_GPIO,  PCD8544_CE_PIN,  GPIO_PIN_RESET); // select
    HAL_SPI_Transmit(&hspi1, &data, 1, HAL_MAX_DELAY);
    HAL_GPIO_WritePin(PCD8544_CE_GPIO,  PCD8544_CE_PIN,  GPIO_PIN_SET);   // deselect
}

// Send entire framebuffer (504 bytes) in one SPI burst
void pcd8544_update(uint8_t *fb) {
    pcd8544_cmd(0x80);  // set X address to 0
    pcd8544_cmd(0x40);  // set Y address (page) to 0
    HAL_GPIO_WritePin(PCD8544_DC_GPIO,  PCD8544_DC_PIN,  GPIO_PIN_SET);
    HAL_GPIO_WritePin(PCD8544_CE_GPIO,  PCD8544_CE_PIN,  GPIO_PIN_RESET);
    HAL_SPI_Transmit(&hspi1, fb, 504, HAL_MAX_DELAY);
    HAL_GPIO_WritePin(PCD8544_CE_GPIO,  PCD8544_CE_PIN,  GPIO_PIN_SET);
}

The DC pin is the key signal here: toggle it LOW before each command byte, HIGH before each data byte. If you leave it in the wrong state, the controller either ignores your data thinking it is a command, or misinterprets commands as pixel data. The pcd8544_update function batches all 504 bytes in a single SPI transaction, which is much faster than 504 individual calls to pcd8544_data — use HAL_SPI_Transmit with the full buffer pointer.

Drawing primitives
uint8_t framebuffer[84 * 6];  // 504 bytes for PCD8544

void setPixel(int x, int y, bool on) {
    if (x &lt; 0 || x &gt;= 84 || y &lt; 0 || y &gt;= 48) return;
    int byte_index = x + (y / 8) * 84;
    uint8_t bit_pos = y % 8;
    if (on) framebuffer[byte_index] |=  (1 &lt;&lt; bit_pos);
    else    framebuffer[byte_index] &= ~(1 &lt;&lt; bit_pos);
}

// Bresenham's line algorithm
void drawLine(int x0, int y0, int x1, int y1) {
    int dx =  abs(x1 - x0), sx = x0 &lt; x1 ? 1 : -1;
    int dy = -abs(y1 - y0), sy = y0 &lt; y1 ? 1 : -1;
    int err = dx + dy;
    for (;;) {
        setPixel(x0, y0, true);
        if (x0 == x1 && y0 == y1) break;
        int e2 = 2 * err;
        if (e2 &gt;= dy) { err += dy; x0 += sx; }
        if (e2 &lt;= dx) { err += dx; y0 += sy; }
    }
}
Call pcd8544_update(framebuffer) after all drawing is complete.

Walk through the byte_index calculation: for pixel (x=5, y=12): page = 12/8 = 1, bit = 12%8 = 4, byte_index = 5 + 1*84 = 89. Set bit 4 of framebuffer[89]. This is the single piece of math that makes page-addressed graphical displays work. Bresenham’s algorithm is a classic — point out that it uses only integer arithmetic (no floating point), which matters on MCUs without an FPU or with slow float operations.

Font rendering & memory tricks
Basic bitmap font — 6×8 pixel ASCII font:

95 printable characters × 6 bytes/glyph = 570 bytes in Flash (const uint8_t[])
Rendering: index into table, copy glyph bytes into framebuffer at the right position

// Render character 'c' at pixel position (x, y) into framebuffer
void drawChar(int x, int y, char c) {
    const uint8_t *glyph = font6x8 + (c - 0x20) * 6;
    for (int col = 0; col &lt; 6; col++) {
        uint8_t column_bits = glyph[col];
        for (int row = 0; row &lt; 8; row++)
            setPixel(x + col, y + row, (column_bits &gt;&gt; row) & 1);
    }
}
Optimization techniques:

Variable-width fonts: only store used glyph widths → saves Flash, harder to render
RLE compression: for glyphs with large white areas, encode run-lengths
Flash placement: use const uint8_t font[] __attribute__((section(".rodata"))) to keep fonts in Flash, not SRAM


The 570 bytes for a full 6×8 ASCII font is a practical number students should internalize: it is nearly free in Flash (512 kB available) but confirms that fonts must live in Flash, not SRAM. Contrast this with a 16×32 Latin Extended font used in some commercial displays — that can be 50+ kB. The column_bits loop is the core of bitmap rendering; trace through it for the letter ‘A’ on the whiteboard if time allows.

DMA for display refresh
Goal: push 1024-byte framebuffer to display without blocking the CPU
// Non-blocking I2C transfer — CPU is free while DMA sends data
uint8_t data_buf[1025];
data_buf[0] = 0x40;  // control byte: data stream
memcpy(&data_buf[1], fb, 1024);
HAL_I2C_Master_Transmit_DMA(&hi2c1, 0x3C &lt;&lt; 1, data_buf, 1025);

// Called by HAL when transfer completes
void HAL_I2C_MasterTxCpltCallback(I2C_HandleTypeDef *hi2c) {
    display_update_done = true;  // signal main loop or RTOS task
}
Why it matters:

Blocking transfer at 400 kHz I²C: ~23 ms — CPU stalls completely
DMA transfer: CPU free to process sensors, update UI state, run RTOS tasks
At 30 FPS, blocking costs 690 ms/s = 69% CPU utilization — unacceptable


This is a preview of what students will encounter in the lab. Run the numbers together: 30 FPS × 23 ms/frame = 690 ms per second wasted waiting. With DMA, that drops to near zero. The callback pattern (MasterTxCpltCallback) is the same one they saw in the DMA/RTOS weeks; point out that display drivers naturally fall into the “producer/consumer” pattern where the main loop produces a framebuffer and the DMA consumer sends it without CPU involvement.

Reference: minimal HD44780 HAL driver
static void set_data_pins(uint8_t nib) {
    HAL_GPIO_WritePin(LCD_D4_GPIO, LCD_D4_PIN, (nib &gt;&gt; 0) & 1);
    HAL_GPIO_WritePin(LCD_D5_GPIO, LCD_D5_PIN, (nib &gt;&gt; 1) & 1);
    HAL_GPIO_WritePin(LCD_D6_GPIO, LCD_D6_PIN, (nib &gt;&gt; 2) & 1);
    HAL_GPIO_WritePin(LCD_D7_GPIO, LCD_D7_PIN, (nib &gt;&gt; 3) & 1);
}

static void lcd_write4(uint8_t nib, bool is_data) {
    HAL_GPIO_WritePin(LCD_RS_GPIO, LCD_RS_PIN, is_data);
    set_data_pins(nib);
    HAL_GPIO_WritePin(LCD_E_GPIO, LCD_E_PIN, GPIO_PIN_SET);
    HAL_Delay(1);  // E pulse width (tPW_E &gt; 450 ns)
    HAL_GPIO_WritePin(LCD_E_GPIO, LCD_E_PIN, GPIO_PIN_RESET);
}

void lcd_send(uint8_t byte, bool is_data) {
    lcd_write4(byte &gt;&gt; 4, is_data);
    lcd_write4(byte & 0x0F, is_data);
    HAL_Delay(1);
}

void lcd_putc(char c)          { lcd_send(c, true); }
void lcd_puts(const char *str) { while (*str) lcd_putc(*str++); }

Use this as the implementation reference after students understand the flow. The full lab driver can add lcd_goto, clear, and initialization wrappers.

